  [0.5,0.75,1,1.25,1.5,1.75].forEach(v=>s+=`<line x1="${X(v)}" x2="${X(v)}" y1="${t}" y2="${H-26}" stroke="${line}"/><text x="${X(v)}" y="${H-10}" text-anchor="middle" font-size="11" fill="${mut}">${fmt(v,2)}</text>`);
  JL.forEach(([n,f,c],i)=>{const y=t+i*rowH; s+=`<text x="${l-8}" y="${y+14}" text-anchor="end" font-size="12">${n}</text><rect x="${X(0.5)}" y="${y+3}" width="${X(f)-X(0.5)}" height="14" rx="3" fill="${col[c]}"/><text x="${X(f)+6}" y="${y+14}" font-size="11.5" font-family="IBM Plex Mono, monospace">${fmt(f,2)}</text>`;});
