const NK=[['Mn²⁺',0.07,960],['V²⁺',0.10,766],['Ni²⁺',0.12,1041],['Mo³⁺',0.15,null],['Cr³⁺',0.20,918],['Fe³⁺',0.24,null],['Rh³⁺',0.28,null],['Ir³⁺',0.28,null],['Co³⁺',0.33,null],['Mn⁴⁺',0.5,null],['Pt⁴⁺',0.6,null],['Pd⁴⁺',0.7,null]];
NK.forEach(([n,k,B],i)=>$('#nMetal').insertAdjacentHTML('beforeend',`<option value="${i}" ${n==='Cr³⁺'?'selected':''}>${n} — k = ${fmt(k,2)}${B?` · B = ${B} cm⁻¹`:''}</option>`));
