function renderCases(){
  const grid=$('#caseGrid'); grid.innerHTML='';
  CASES.forEach((c,i)=>{
    const el=document.createElement('article'); el.className='case';
    el.innerHTML=`<div class="meta">${c.meta}</div><h4>${c.title}</h4><div class="fig">${c.fig()}</div><p>${c.text}</p><ul>${c.bul.map(b=>`<li>${b}</li>`).join('')}</ul><div class="actions"></div>`;
    c.act.forEach(([lab,fn])=>{const b=document.createElement('button'); b.className='btn'; b.textContent=lab; b.addEventListener('click',fn); el.querySelector('.actions').appendChild(b);});
    grid.appendChild(el);
  });
}
function openEx(i){ $('#exPreset').value=i; applyExPreset(PRESETS[i]); goTo('geometrias'); }
function openFit(i){ const p=FITP[i]; $('#fitPreset').value=i; $('#fitObs').value=p.obs.join(', '); ts.n=p.n; setSeg('#tsN','n',p.n); runFit(); goTo('ts'); }
function openWalsh(p){ walsh.path=p; setSeg('#walshPath','p',p); drawWalsh(); goTo('walsh'); }

/* ===== Excepciones y límites ===== */
function drawHier(){
  const mut=css('--muted'),line=css('--line'),up=css('--up'),dn=css('--down'),acc=css('--accent'),c4=css('--c4');
  const W=660,H=250,l=180,r=20,t=34,rowH=26;
  const X=v=>l+(Math.log10(v)-1)/(5-1)*(W-l-r);
  const rows=[['3d: repulsión e⁻–e⁻ (B, C)',8000,40000,acc],['3d: campo de ligandos Δ',7000,40000,up],['3d: espín–órbita ζ',80,800,dn],
              ['4f: repulsión e⁻–e⁻',10000,40000,acc],['4f: espín–órbita ζ',600,3000,dn],['4f: campo de ligandos',50,500,up]];
  let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="Jerarquía de perturbaciones en iones 3d y 4f">`;
  [10,100,1000,10000,100000].forEach(v=>s+=`<line x1="${X(v)}" x2="${X(v)}" y1="${t-6}" y2="${t+rows.length*rowH+10}" stroke="${line}"/><text x="${X(v)}" y="${t-12}" text-anchor="middle" font-size="11" fill="${mut}">${v>=1000?fmtInt(v):v}</text>`);
  rows.forEach(([n,a,b,c],i)=>{const y=t+i*rowH+(i>=3?12:0); s+=`<text x="${l-10}" y="${y+14}" text-anchor="end" font-size="12">${n}</text><rect x="${X(a)}" y="${y+3}" width="${X(b)-X(a)}" height="15" rx="4" fill="${c}" opacity=".85"/>`;});
  s+=`<line x1="12" x2="${W-r}" y1="${t+3*rowH+5}" y2="${t+3*rowH+5}" stroke="${mut}" stroke-dasharray="4 4"/>`;
  s+=`<text x="12" y="${H-10}" font-size="11.5" fill="${mut}">3d: Δ ≫ ζ → la TCC funciona.  4f: ζ ≫ campo → líneas finas y magnetismo de ion libre (J).</text>`;
  $('#figHier').innerHTML=s+'</svg>';
}
function invFig(){
  const ink=css('--ink'),mut=css('--muted'),up=css('--up'),dn=css('--down'),acc=css('--accent');
  const W=320,H=200; const L=(x,y,w,c,t)=>`<line x1="${x}" y1="${y}" x2="${x+w}" y2="${y}" stroke="${c}" stroke-width="3.2" stroke-linecap="round"/><text x="${x+w/2}" y="${y+14}" text-anchor="middle" font-size="10.5" fill="${mut}">${t}</text>`;
  let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="Campo de ligandos normal e invertido">`;
  s+=`<text x="80" y="14" text-anchor="middle" font-size="12" font-weight="600">normal</text><text x="240" y="14" text-anchor="middle" font-size="12" font-weight="600">invertido</text>`;
  s+=L(20,60,50,mut,'d (M)')+L(95,45,50,up,'σ* (≈ d)')+L(95,150,50,ink,'σ (≈ L)')+L(20,170,50,mut,'σ (L)');
  s+=L(250,60,50,mut,'σ (L)')+L(175,45,50,up,'σ* (≈ L)')+L(175,150,50,ink,'σ (≈ d)')+L(250,175,50,mut,'d (M)');
  s+=`<line x1="160" y1="25" x2="160" y2="${H-10}" stroke="${css('--line')}"/>`;
  s+=`<text x="160" y="${H-2}" text-anchor="middle" font-size="10.5" fill="${acc}">el hueco “del metal” está en realidad en los ligandos</text>`;
  return s+'</svg>';
}
