['dbQ','dbN','dbGeo'].forEach(id=>$('#'+id).addEventListener('input',renderDB));
function renderDB(){
  const q=$('#dbQ').value.trim().toLowerCase(), n=$('#dbN').value, g=$('#dbGeo').value;
  const rows=DB.filter(r=>{ if(n!==''&&r.n!==+n) return false; if(g){ if(['oct','tet','sqp'].includes(g)&&r.geo!==g) return false; if(g==='AE'&&r.spin!=='AE') return false; if(g==='BE'&&r.spin!=='BE') return false; }
    if(q){ const hay=(r.f+' '+r.ion+' '+r.cname+' '+r.note+' '+({oct:'octaédrico',tet:'tetraédrico',sqp:'plano cuadrado'}[r.geo])).toLowerCase(); if(!hay.includes(q)) return false; } return true; });
  let h='<thead><tr><th>Complejo</th><th>Ion</th><th>dⁿ</th><th>Geom.</th><th>Espín</th><th>Bandas (cm⁻¹)</th><th>Δ (cm⁻¹)</th><th>μ (MB)</th><th>Color</th><th>Nota</th><th></th></tr></thead><tbody>';
  rows.forEach(r=>{ const i=DB.indexOf(r);
    h+=`<tr><td>${r.f}</td><td>${r.ion}</td><td class="m">d${sup(r.n)}</td><td>${GEON[r.geo]}</td><td>${r.spin==='AE'?'<span class="pill hs">AE</span>':r.spin==='BE'?'<span class="pill ls">BE</span>':r.spin}</td><td class="m">${r.bands.length?r.bands.map(fmtInt).join(', '):'—'}</td><td class="m">${r.D?fmtInt(r.D)+(r.geo==='tet'?' (Δt)':''):'—'}</td><td class="m">${r.mu==null?'—':fmt(r.mu,1)}</td><td><span style="display:inline-flex;align-items:center;gap:6px"><i style="display:inline-block;width:14px;height:14px;border-radius:50%;border:1px solid var(--line);background:${r.col}"></i>${r.cname}</span></td><td class="wrap" style="min-width:200px">${r.note.replace(/e_g/g,'e<sub>g</sub>')}</td><td><button class="btn" data-db="${i}">Abrir</button></td></tr>`; });
  $('#dbTable').innerHTML=h+'</tbody>';
  $('#dbCount').textContent=`${rows.length} de ${DB.length} complejos. Valores redondeados de tablas estándar; μ a temperatura ambiente.`;
  $('#dbTable').querySelectorAll('button[data-db]').forEach(b=>b.addEventListener('click',()=>openDB(DB[+b.dataset.db])));
}
function openDB(r){
  if([2,3,7,8].includes(r.n)&&r.geo==='oct'&&r.bands.length>=2){ ts.n=r.n; setSeg('#tsN','n',r.n); $('#fitObs').value=r.bands.join(', '); runFit(); goTo('ts'); return; }
  if(['oct','tet','sqp'].includes(r.geo)&&r.n>0&&r.n<10){ const D=r.D?(r.geo==='tet'?r.D*9/4:r.D):(r.geo==='sqp'?30000:20000); const P=PAIR[r.ion]||17000;
    applyExPreset({g:r.geo,n:r.n,D:Math.min(40000,D),P,mode:r.spin==='AE'?'hs':r.spin==='BE'?'ls':'auto'}); $('#exPreset').value=0; goTo('geometrias'); return; }
  goTo('color');
}
const PAIR={'Cr²⁺':23500,'Mn³⁺':28000,'Mn²⁺':25500,'Fe³⁺':30000,'Fe²⁺':17600,'Co³⁺':21000,'Co²⁺':22500};

/* ---------- generador de ejercicios ---------- */
const GM=[['Mn²⁺','Mn',2,5,8.0,25500],['Ni²⁺','Ni',2,8,8.7,null],['Co²⁺','Co',2,7,9.0,22500],['V²⁺','V',2,3,12.0,null],['Fe³⁺','Fe',3,5,14.0,30000],['Cr³⁺','Cr',3,3,17.4,null],['Co³⁺','Co',3,6,18.2,21000],['Ru²⁺','Ru',2,6,20.0,'4d'],['Mn⁴⁺','Mn',4,3,23.0,null],['Mo³⁺','Mo',3,3,24.0,null],['Rh³⁺','Rh',3,6,27.0,'4d'],['Ir³⁺','Ir',3,6,32.0,'5d'],['Pt⁴⁺','Pt',4,6,36.0,'5d'],['Cu²⁺','Cu',2,9,12.5,null],['Ti³⁺','Ti',3,1,20.3,null]];
const GL=[['Br⁻',0.72,-1,6,'Br'],['Cl⁻',0.78,-1,6,'Cl'],['F⁻',0.90,-1,6,'F'],['ox²⁻',0.99,-2,3,'ox'],['H₂O',1.00,0,6,'H₂O'],['py',1.23,0,6,'py'],['NH₃',1.25,0,6,'NH₃'],['en',1.28,0,3,'en'],['bipy',1.33,0,3,'bipy'],['CN⁻',1.70,-1,6,'CN']];
const chargeStr=z=>z===0?'':(Math.abs(z)>1?sup(Math.abs(z)):'')+(z>0?'⁺':'⁻');
const rnd=a=>a[Math.floor(Math.random()*a.length)];
function makeExercise(level){
  for(let tries=0;tries<200;tries++){
    const geoPick=level==='basico'?'oct':rnd(['oct','oct','oct','tet','sqp']);
    if(geoPick==='oct'){ const M=rnd(GM), L=rnd(GL); const [ion,sym,ox,n,g,P]=M; const [ln,f,lz,cnt,lf]=L;
      if(L[4]==='CN'&&n>=4&&n<=7&&typeof P==='number') continue;             // Jørgensen falla con CN⁻ en 3d de espín intermedio
      const D=Math.round(f*g*1000/10)*10; let spin='—', amb=n>=4&&n<=7;
      if(amb){ if(typeof P==='number'){ const Pc=0.85*P; if(Math.abs(D-Pc)/Pc<0.25) continue; spin=D>Pc?'BE':'AE'; } else { if(D<20000) continue; spin='BE'; } }
      const occ=bestConfig(GEO.oct.E,n,spin==='BE'?0:1e9).occ; const unp=occ.filter(o=>o===1).length; const cf=occ.reduce((s,o,i)=>s+o*GEO.oct.E[i],0)/10;
      const z=ox+cnt*lz; const lig= cnt===6?`(${lf})₆`:`(${lf})₃`;
      const lamOK=[1,3,8,9].includes(n)||(spin==='AE'&&(n===4||n===6));
      return {f:`[${sym}${lig}]${chargeStr(z)}`, ion, ox, n, geo:'oct', D, P:typeof P==='number'?Math.round(0.85*P):null, heavy:typeof P==='string'?P:null, spin, unp, cf, cfu:'Δo', mu:Math.sqrt(unp*(unp+2)), lam:lamOK?1e7/D:null, src:`Δo ≈ f·g = ${fmt(f,2)} × ${fmt(g,1)}·10³ = ${fmtInt(D)} cm⁻¹ (Jørgensen)`};
    }
    if(geoPick==='tet'){ const M=rnd(GM.filter(m=>['Co²⁺','Ni²⁺','Mn²⁺','Cu²⁺'].includes(m[0]))), X=rnd([['Cl',0.78],['Br',0.72]]); const [ion,sym,ox,n,g]=M;
      const D=Math.round(4/9*X[1]*g*1000/10)*10; const occ=bestConfig([-8/3,-8/3,16/9,16/9,16/9],n,1e9).occ; const unp=occ.filter(o=>o===1).length; const cf=occ.reduce((s,o,i)=>s+o*[-0.6,-0.6,0.4,0.4,0.4][i],0);
      return {f:`[${sym}${X[0]}₄]²⁻`, ion, ox, n, geo:'tet', D, spin:(n>=3&&n<=6)?'AE':'—', unp, cf, cfu:'Δt', mu:Math.sqrt(unp*(unp+2)), lam:null, src:`Δt ≈ 4/9 · f·g = ${fmtInt(D)} cm⁻¹: siempre menor que P → alto espín`};
    }
    const M=rnd([['Ni²⁺','[Ni(CN)₄]²⁻'],['Pd²⁺','[PdCl₄]²⁻'],['Pt²⁺','[PtCl₄]²⁻'],['Au³⁺','[AuCl₄]⁻'],['Pt²⁺','[Pt(NH₃)₄]²⁺']]);
    const occ=bestConfig(GEO.sqp.E,8,0).occ; const cf=occ.reduce((s,o,i)=>s+o*GEO.sqp.E[i],0);
    return {f:M[1], ion:M[0], ox:+(M[0].includes('³')?3:2), n:8, geo:'sqp', D:null, spin:'BE', unp:0, cf, cfu:'Dq', mu:0, lam:null, src:'d⁸ con campo fuerte (o metal 4d/5d): d_x²−y² muy alto y vacío'};
  }
}
let curEx=null;
function renderGen(){
  curEx=makeExercise($('#genLevel').value); const e=curEx;
  const geoTxt={oct:'octaédrico',tet:'tetraédrico',sqp:'plano cuadrado'}[e.geo];
  $('#genQ').innerHTML=`<p class="prose" style="margin:0 0 6px"><b>Complejo:</b> <span style="font-size:20px;font-family:var(--font-display)">${e.f}</span> (${geoTxt}). ${e.geo==='oct'&&e.D?`Dato: Δo ≈ ${fmtInt(e.D)} cm⁻¹${e.P?`, P ≈ ${fmtInt(e.P)} cm⁻¹ en el complejo`:e.heavy?`; metal ${e.heavy}`:''}.`:''}${e.geo==='tet'?` Dato: Δt ≈ ${fmtInt(e.D)} cm⁻¹.`:''}</p>
   <div class="gen-grid">
    <div class="ctl"><label for="gN">Electrones d (n)</label><input type="number" id="gN" min="0" max="10"></div>
    <div class="ctl"><label for="gS">Espín</label><select id="gS"><option value="">—</option><option value="AE">alto espín</option><option value="BE">bajo espín</option><option value="—">no aplica (una sola opción)</option></select></div>
    <div class="ctl"><label for="gU">e⁻ desapareados</label><input type="number" id="gU" min="0" max="5"></div>
    <div class="ctl"><label for="gC">EECC (en ${e.cfu}, sin P)</label><input type="number" id="gC" step="0.01"></div>
    <div class="ctl"><label for="gM">μ solo espín (MB)</label><input type="number" id="gM" step="0.01"></div>
    <div class="ctl"><label for="gL">λ de la banda d–d de menor energía (nm)</label><input type="number" id="gL" step="1" placeholder="${e.lam?'':'no aplica: déjalo vacío'}"></div>
   </div>
   <div class="seg"><button class="btn primary" id="gCheck">Comprobar</button><button class="btn" id="gShow">Ver solución</button></div><div id="gRes" style="margin-top:10px"></div>`;
  $('#gCheck').addEventListener('click',()=>checkGen(false)); $('#gShow').addEventListener('click',()=>checkGen(true));
}
function solutionHTML(e){
  const steps=[`<b>1. Electrones d.</b> ${e.ion}: el metal tiene estado de oxidación +${e.ox} → d${sup(e.n)}.`];
  if(e.geo==='oct') steps.push(`<b>2. Campo.</b> ${e.src}. ${e.spin==='—'?'Con d'+sup(e.n)+' solo hay una configuración posible.':e.heavy?`Metal ${e.heavy}: Δ grande y P pequeño → bajo espín.`:`Δo ${e.spin==='BE'?'>':'<'} P (${fmtInt(e.P)} cm⁻¹) → ${e.spin==='BE'?'bajo':'alto'} espín.`}`);
  else steps.push(`<b>2. Campo.</b> ${e.src}.`);
  steps.push(`<b>3. Configuración.</b> ${e.unp} electrones desapareados.`);
  steps.push(`<b>4. EECC.</b> ${fmt(e.cf,2)} ${e.cfu}${e.geo==='oct'&&e.D?` = ${fmtInt(e.cf*e.D)} cm⁻¹ ≈ ${fmt(e.cf*e.D*CM2KJ,0)} kJ/mol`:''}.`);
  steps.push(`<b>5. Magnetismo.</b> μ = √[n(n+2)] = ${fmt(e.mu,2)} MB.`);
  steps.push(`<b>6. Color.</b> ${e.lam?`La primera banda d–d está en Δ: λ = 10⁷/${fmtInt(e.D)} = ${fmt(e.lam,0)} nm (absorbe ${colorInfo(e.lam).abs}, se vería ${colorInfo(e.lam).obs}).`:'No aplica: la primera banda no es igual a Δ (o no hay bandas permitidas por espín / transferencia de carga).'}`);
  return steps.map(s=>`<div style="margin:4px 0">${s}</div>`).join('');
}
function checkGen(show){
  const e=curEx, v=id=>$('#'+id).value.trim();
  const res=[]; const mark=(ok,lab,ans)=>res.push(`<span class="${ok?'mark-ok':'mark-bad'}">${ok?'✓':'✗'} ${lab}</span>${ok?'':` <span style="color:var(--muted)">(correcto: ${ans})</span>`}`);
  if(!show){
    mark(+v('gN')===e.n,'n',e.n);
    mark(v('gS')===e.spin,'espín',{AE:'alto espín',BE:'bajo espín','—':'no aplica'}[e.spin]);
    mark(+v('gU')===e.unp,'desapareados',e.unp);
    mark(v('gC')!==''&&Math.abs(+v('gC')-e.cf)<=(e.cfu==='Dq'?0.15:0.051),'EECC',fmt(e.cf,2)+' '+e.cfu);
    mark(v('gM')!==''&&Math.abs(+v('gM')-e.mu)<=0.06,'μ',fmt(e.mu,2)+' MB');
    mark(e.lam?(v('gL')!==''&&Math.abs(+v('gL')-e.lam)/e.lam<=0.08):v('gL')==='', 'λ', e.lam?fmt(e.lam,0)+' nm':'dejar vacío');
  }
  $('#gRes').innerHTML=(res.length?`<div style="display:flex;flex-wrap:wrap;gap:6px 16px;margin-bottom:8px">${res.join('')}</div>`:'')+`<details ${show?'open':''}><summary>Resolución paso a paso</summary>${solutionHTML(e)}</details>`;
}
