/* ---------- problemas guiados ---------- */
const GUIDED=[
 {t:'Problema A · Asignar un espectro y obtener Δo, B y β',st:'Una disolución azul-violeta de [Ni(NH₃)₆]²⁺ muestra tres bandas débiles (ε ≈ 5) a 10 750, 17 500 y 28 200 cm⁻¹; μ = 3,1 MB. B del ion libre = 1 041 cm⁻¹.',
  steps:['Ni²⁺ es d⁸. En O<sub>h</sub> el fundamental es ³A₂g (t₂g⁶e_g²): 2 e⁻ desapareados, μ<sub>so</sub> = 2,83 MB. El valor medido (3,1) es algo mayor por mezcla espín–órbita (α = 4, λ &lt; 0).','Las tres bandas permitidas por espín son ³A₂g → ³T₂g, ³T₁g(F) y ³T₁g(P). Para d⁸, ν₁ = Δo: Δo = 10 750 cm⁻¹.','B = (2ν₁² + ν₂² − 3ν₁ν₂)/(15ν₂ − 27ν₁) = (2·10 750² + 17 500² − 3·10 750·17 500)/(15·17 500 − 27·10 750) ≈ 870 cm⁻¹.','β = 870/1 041 ≈ 0,84: más covalente que con H₂O (β ≈ 0,9), como predice la serie nefelauxética (h(NH₃) &gt; h(H₂O)). Compruébalo con el botón de ajuste.'],
  act:['Abrir en el ajuste',()=>{ts.n=8;setSeg('#tsN','n',8);$('#fitObs').value='10750, 17500, 28200';runFit();goTo('ts');}]},
 {t:'Problema B · ¿Octaédrico o tetraédrico?',st:'Un complejo de Co(II) con cloruro y una fosfina es azul intenso (ε ≈ 500 L mol⁻¹ cm⁻¹ hacia 15 000 cm⁻¹) y tiene μ = 4,5 MB a 300 K.',
  steps:['Co²⁺ es d⁷. Un octaedro de alto espín tendría 3 e⁻ desapareados y un tetraedro también: el número de electrones desapareados no basta.','La intensidad decide: ε ≈ 500 es típico de complejos sin centro de inversión (T<sub>d</sub>); un octaedro daría ε ≈ 5–10.','El momento: en T<sub>d</sub> el fundamental es ⁴A₂ (sin contribución orbital de primer orden) → μ ≈ 4,4–4,8 MB; en O<sub>h</sub>, ⁴T₁g daría 4,7–5,2 MB. 4,5 encaja con T<sub>d</sub>.','Conclusión: tetraédrico. La banda a ≈ 15 000 cm⁻¹ es ⁴A₂ → ⁴T₁(P), que en T<sub>d</sub> cae en el rojo y da el color azul.']},
 {t:'Problema C · Leer un espectro EPR',st:'Un complejo de Cu(II) en vidrio congelado da g<sub>∥</sub> = 2,27, g<sub>⊥</sub> = 2,06 y cuatro líneas hiperfinas en la región paralela. La banda d–d está a ≈ 16 000 cm⁻¹.',
  steps:['g<sub>∥</sub> &gt; g<sub>⊥</sub> &gt; 2,0023 → el electrón desapareado está en d<sub>x²−y²</sub>: octaedro alargado o plano cuadrado (no comprimido).','Con g<sub>∥</sub> = 2,0023 − 8λk²/ΔE y λ = −830 cm⁻¹, ΔE ≈ 16 000 cm⁻¹: k² = (2,27 − 2,0023)·16 000/(8·830) ≈ 0,65.','k² ≈ 0,65 &lt; 1 indica que ≈ 35 % de la densidad de espín está deslocalizada en los ligandos: enlace bastante covalente.','Las cuatro líneas vienen del núcleo ⁶³/⁶⁵Cu (I = 3/2): 2I + 1 = 4.'],
  act:['Abrir el simulador EPR',()=>{$('#eprK').value=0.65;$('#eprXY').value=16000;drawEPR();goTo('epr');}]},
 {t:'Problema D · ¿Espinela normal o inversa?',st:'Predice si CoFe₂O₄ (Co²⁺ + 2 Fe³⁺) y ZnFe₂O₄ (Zn²⁺ + 2 Fe³⁺) serán espinelas normales o inversas.',
  steps:['Fe³⁺ es d⁵ de alto espín: EECC = 0 en ambos huecos, no tiene preferencia.','Co²⁺ es d⁷ AE: EECC(oct) = −0,8 Δo, EECC(tet) = −1,2 Δt ≈ −0,53 Δo. EPSO ≈ 0,27 Δo: prefiere el octaedro → desplaza a Fe³⁺ a los tetraedros → inversa.','Zn²⁺ es d¹⁰: EPSO = 0, y por su tamaño y su enlace covalente sp³ prefiere el tetraedro → normal.','Observado: CoFe₂O₄ es mayoritariamente inversa; ZnFe₂O₄, normal. La TCC acierta la tendencia; el grado exacto de inversión depende también del tamaño y del método de síntesis.'],
  act:['Ver la estructura',()=>{xtal.k='inverse';setSeg('#xtalSel','x','inverse');renderXtal();goTo('estructuras');}]}
];
function renderGuided(){
  $('#guided').innerHTML=GUIDED.map((g,i)=>`<div class="lab" data-g="${i}"><div class="lab-title"><span class="tag">Guiado</span> <span>${g.t}</span></div><p class="prose" style="margin-top:0">${g.st.replace(/e_g/g,'e<sub>g</sub>')}</p><div class="steps guided-steps">${g.steps.map(s=>`<div class="step">${s.replace(/e_g/g,'e<sub>g</sub>')}</div>`).join('')}</div><div class="seg"><button class="btn primary" data-a="next">Siguiente pista</button><button class="btn" data-a="all">Ver solución completa</button><button class="btn" data-a="reset">Reiniciar</button>${g.act?'<button class="btn" data-a="lab">'+g.act[0]+'</button>':''}</div></div>`).join('');
  $('#guided').querySelectorAll('[data-g]').forEach(box=>{ const g=GUIDED[+box.dataset.g]; const steps=[...box.querySelectorAll('.step')];
    box.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{ const a=b.dataset.a;
      if(a==='next'){ const k=steps.findIndex(s=>!s.classList.contains('on')); if(k>=0) steps[k].classList.add('on'); }
      if(a==='all') steps.forEach(s=>s.classList.add('on')); if(a==='reset') steps.forEach(s=>s.classList.remove('on')); if(a==='lab') g.act[1](); })); });
}

/* ---------- fichas ---------- */
const CARDS=[['Δo frente a Δt','Δt ≈ 4/9 Δo (mismos ligandos y distancia)'],['Energías octaédricas','e<sub>g</sub>: +0,6 Δo · t₂g: −0,4 Δo'],['Criterio de espín','Δ &gt; P → bajo espín; Δ &lt; P → alto espín'],['μ solo espín','√[n(n+2)] MB'],['Iones con Jahn–Teller fuerte','d⁹, d⁴ AE, d⁷ BE (degeneración en e<sub>g</sub>)'],['Serie espectroquímica (resumen)','I⁻ &lt; Br⁻ &lt; Cl⁻ &lt; F⁻ &lt; H₂O &lt; NH₃ &lt; en &lt; bipy &lt; CN⁻ &lt; CO'],['Regla de Laporte','Prohibidas las transiciones g → g: las d–d octaédricas son débiles (ε ≈ 1–10)'],['ε típico tetraédrico','10²–10³ L mol⁻¹ cm⁻¹ (sin centro de inversión)'],['Fundamental de d³ y d⁸ en O<sub>h</sub>','⁴A₂g y ³A₂g; ν₁ = Δo'],['Separación ³P–³F','15B'],['Regla de Jørgensen','Δo ≈ f(ligando)·g(metal)'],['Parámetro nefelauxético','β = B<sub>complejo</sub>/B<sub>libre</sub>; 1 − β ≈ h·k'],['AOM octaédrico','Δo = 3e<sub>σ</sub> − 4e<sub>π</sub>'],['π-donador frente a π-aceptor','π-donador: e<sub>π</sub> &gt; 0, reduce Δ; π-aceptor: e<sub>π</sub> &lt; 0, aumenta Δ'],['EPSO','EECC(tet) − EECC(oct): grande para d³, d⁸ y d⁴ AE'],['Irving–Williams','Mn &lt; Fe &lt; Co &lt; Ni &lt; Cu &gt; Zn'],['Complejos inertes típicos','d³ (Cr³⁺) y d⁶ BE (Co³⁺, Rh³⁺, Pt⁴⁺): EACC grande'],['g de Cu(II) alargado','g<sub>∥</sub> &gt; g<sub>⊥</sub> &gt; 2,0023 (fundamental d<sub>x²−y²</sub>)'],['Lantánidos','ζ ≫ campo: μ = g<sub>J</sub>√[J(J+1)], líneas finas'],['T½ de transición de espín','T½ = ΔH/ΔS; histéresis si Γ &gt; 2RT½'],['Contribución orbital','Solo términos T (p. ej. ⁴T₁g de Co²⁺, ⁵T₂g de Fe²⁺)'],['Efecto trans (Pt²⁺)','CO, CN⁻ &gt; PR₃ &gt; I⁻ &gt; Br⁻ &gt; Cl⁻ &gt; NH₃ &gt; H₂O']];
const fl={i:0,order:CARDS.map((_,i)=>i),know:0,rev:0};
function renderFlash(){
  const c=CARDS[fl.order[fl.i]];
  $('#flash').innerHTML=`<div class="flash-card" id="fc" tabindex="0" role="button" aria-label="Ficha: pulsa para girar"><div class="flash-inner"><div class="flash-face">${c[0]}</div><div class="flash-face flash-back">${c[1]}</div></div></div>
   <div class="seg" style="justify-content:center;margin-top:12px"><button class="btn" id="fPrev">← Anterior</button><button class="btn" id="fFlip">Girar</button><button class="btn" id="fNext">Siguiente →</button><button class="btn" id="fShuf">Barajar</button><button class="btn" id="fKnow">Lo sé</button><button class="btn" id="fRev">Repasar</button></div>
   <div class="caption" style="text-align:center">Ficha ${fl.i+1} de ${CARDS.length} · sabidas: ${fl.know} · por repasar: ${fl.rev}</div>`;
  const flip=()=>$('#fc').classList.toggle('flip');
  $('#fc').addEventListener('click',flip); $('#fc').addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();flip();}});
  $('#fFlip').addEventListener('click',flip);
  $('#fPrev').addEventListener('click',()=>{fl.i=(fl.i-1+CARDS.length)%CARDS.length;renderFlash();});
  $('#fNext').addEventListener('click',()=>{fl.i=(fl.i+1)%CARDS.length;renderFlash();});
  $('#fShuf').addEventListener('click',()=>{fl.order.sort(()=>Math.random()-0.5);fl.i=0;renderFlash();});
  $('#fKnow').addEventListener('click',()=>{fl.know++;fl.i=(fl.i+1)%CARDS.length;renderFlash();});
  $('#fRev').addEventListener('click',()=>{fl.rev++;fl.i=(fl.i+1)%CARDS.length;renderFlash();});
}

