function applyTheme(t){
  if(t==='system') document.documentElement.removeAttribute('data-theme'); else document.documentElement.setAttribute('data-theme',t);
  document.querySelectorAll('.theme button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.t===t?'true':'false'));
  try{ localStorage.setItem('cristalia-theme',t); }catch(e){}
}
