  // B2H6
  { const B=[[-0.885,0,0],[0.885,0,0]]; out.B2H6={heavy:B,E:[],Ht:[[-1.48,0,1.03],[-1.48,0,-1.03],[1.48,0,1.03],[1.48,0,-1.03]].map((p,k)=>({p,to:k<2?0:1})),Hb:[{p:[0,0.99,0],a:0,b:1},{p:[0,-0.99,0],a:0,b:1}],styx:'2002',m:2,n:6,q:0}; }
  // B4H10 (arachno, mariposa)
  { const B=[[0,0.87,0],[0,-0.87,0],[1.45,0,0.55],[-1.45,0,0.55]]; const Ht=[{p:[0,1.6,-0.9],to:0},{p:[0,-1.6,-0.9],to:1},{p:[2.3,0,1.35],to:2},{p:[2.2,0,-0.4],to:2},{p:[-2.3,0,1.35],to:3},{p:[-2.2,0,-0.4],to:3}];
    const Hb=[[0,2],[0,3],[1,2],[1,3]].map(([a,b])=>{ const mid=v3s(v3add(B[a],B[b]),0.5); return {p:v3add(mid,[Math.sign(mid[0])*0.35,Math.sign(mid[1])*0.65,0.55]),a,b}; });
    out.B4H10={heavy:B,E:[[0,1],[0,2],[0,3],[1,2],[1,3]],Ht,Hb,styx:'4012',m:4,n:10,q:0}; }
  // B5H9 (nido, pirámide cuadrada)
  { const B=[[0,0,1.11],[0.9,0.9,0],[-0.9,0.9,0],[-0.9,-0.9,0],[0.9,-0.9,0]]; const E=[[0,1],[0,2],[0,3],[0,4],[1,2],[2,3],[3,4],[4,1]];
    out.B5H9={heavy:B,E,Ht:radialH(B,[0,1,2,3,4]),Hb:[[1,2],[2,3],[3,4],[4,1]].map(([a,b])=>bridge(B,a,b,1.6,-0.45)),styx:'4120',m:5,n:9,q:0}; }
  // B6H10 (nido, pirámide pentagonal)
  { const R=1.514, B=[[0,0,0.878]]; for(let i=0;i<5;i++){ const a=Math.PI/2+i*2*Math.PI/5; B.push([R*Math.cos(a),R*Math.sin(a),0]); } const E=[]; for(let i=1;i<=5;i++){ E.push([0,i]); E.push([i,i%5+1]); }
    out.B6H10={heavy:B,E,Ht:radialH(B,[0,1,2,3,4,5]),Hb:[[2,3],[3,4],[4,5],[5,1]].map(([a,b])=>bridge(B,a,b,1.6,-0.45)),styx:'4220',m:6,n:10,q:0}; }
