    const E=[[0,1],[0,2],[0,3],[0,4],[1,2],[2,3],[3,4]]; const Ht=radialH(B,[0,1,2,3,4]);
    Ht.push({p:v3add(B[1],[0,0,-1.19]),to:1},{p:v3add(B[4],[0,0,-1.19]),to:4},{p:v3add(B[0],v3s(v3n(v3sub(miss,B[0])),1.19)),to:0});
