let molDone=false, crDone=false;
function renderMolTab(){ renderMol(); renderDiat(); renderAr(); renderPl(); renderBo(); renderBc(); molDone=true; }
function renderCrTab(){ if(!crDone){ renderSysCtrls(); } renderSys(); renderCl(); renderCN(); renderXrd(); renderXrf(); crDone=true; }
