const GCAT={ok:['permitida','#1c6dd0'],lap:['prohibida por Laporte (misma paridad: s↔s, s↔d, p↔p, d↔d…)','#d6336c'],dl:['prohibida: ΔL o Δl mayor que 1 (s↔f, p↔g…)','#e67700'],spin:['intercombinación ΔS ≠ 0','#0ca678'],J:['prohibida por J (0 ↔ 0 o ΔJ > 1)','#868e96']};
function airL(nmVac){ if(nmVac<200) return nmVac; const s=1000/nmVac, s2=s*s; const n=1+1e-8*(8342.13+2406030/(130-s2)+15997/(38.9-s2)); return nmVac/n; }
function grCat(G,lo,up,Jl,Ju){ if(lo.par===up.par) return 'lap';
  if(Jl!=null&&Ju!=null&&((Jl===0&&Ju===0)||Math.abs(Jl-Ju)>1)) return 'J';
  if(Math.abs(up.L-lo.L)>1) return 'dl';
  if(lo.S!==up.S) return 'spin';
  return 'ok'; }
function grLines(k){ const G=GROT[k], L=G.lev, out=[];
  for(let i=0;i<L.length;i++) for(let j=0;j<L.length;j++){ const lo=L[i], up=L[j]; if(up.E<=lo.E) continue;
    const pairs=[]; if(G.one&&(lo.Js||up.Js)){ (lo.Js||[[null,lo.E]]).forEach(([Jl,El])=>(up.Js||[[null,up.E]]).forEach(([Ju,Eu])=>pairs.push({Jl:Jl==null?(lo.l?null:0.5):Jl,Ju:Ju==null?(up.l?null:0.5):Ju,El,Eu}))); } else pairs.push({Jl:G.two?lo.J:null,Ju:G.two?up.J:null,El:lo.E,Eu:up.E});
    pairs.forEach(p=>{ const sig=p.Eu-p.El; if(sig<1) return; const cat=grCat(G,lo,up,p.Jl==null?null:p.Jl,p.Ju==null?null:p.Ju); const vac=1e7/sig;
      out.push({lo,up,cat,ok:cat==='ok'?true:cat==='spin'?'ic':false,nm:airL(vac),eV:sig/8065.544,res:lo.E===0,Jl:p.Jl,Ju:p.Ju,calc:lo.calc||up.calc}); }); }
  return out.sort((a,b)=>a.nm-b.nm); }
function region(nm){ return nm<200?'UV de vacío':nm<380?'UV':nm<750?'visible':nm<3000?'IR cercano':nm<50000?'IR medio':'IR lejano / microondas'; }
const grF={lap:false,dl:false,spin:true,J:false};
let grK='Na', grMode='abs', grSel=null, grLv=null;
const jTxt=J=>J==null?'':J%1?(2*J)+'/2':String(J);
function renderGrot(){ const G=GROT[grK], L=G.lev, all=grLines(grK), cat=t=>t.cat;
  let show=all.filter(t=>{ if(grLv!=null){ return t.lo===L[grLv]||t.up===L[grLv]; } if(t.cat!=='ok'&&!grF[t.cat]) return false; return grMode==='abs'?t.res:true; });
  const W=700, H=486, ink=css('--ink'), mut=css('--muted'), nc=G.cols.length, colW=(W-110)/nc, colX=c=>58+c*colW, lw=Math.min(52,colW-30);
  const Emax=G.lim*1.02, Y=E=>H-50-E/Emax*(H-86);
  let s=`<svg viewBox="0 0 ${W} ${H}" width="100%" style="max-width:${W}px" role="img" aria-label="Diagrama de niveles (Grotrian)" id="grSvg"><defs><marker id="gra" markerUnits="userSpaceOnUse" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8Z" fill="context-stroke"/></marker></defs>`;
  G.cols.forEach((n,c)=>{ s+=`<text x="${colX(c)+lw/2}" y="16" text-anchor="middle" font-size="${n.length>3?11:13}" font-weight="700" fill="${c===5&&G.one?mut:ink}">${n}</text>`; });
  s+=`<line x1="40" y1="${Y(G.lim)}" x2="${W-10}" y2="${Y(G.lim)}" stroke="${mut}" stroke-dasharray="6 4"/><text x="${W-12}" y="${Y(G.lim)-4}" text-anchor="end" font-size="11" fill="${mut}">ionización ${fmt(G.lim/8065.544,2)} eV</text>`;
  for(let e=0;e<=G.lim/8065.544;e+=(G.lim>150000?5:1)) s+=`<text x="4" y="${Y(e*8065.544)+4}" font-size="10" fill="${mut}">${e} eV</text>`;
  // líneas (debajo de los niveles)
  const seen=new Set(); show.forEach((t,k)=>{ const key=t.lo.c+'|'+t.up.c+'|'+t.cat; if(seen.has(key)) return; seen.add(key); const off=((k%5)-2)*5, x1=colX(t.lo.col)+lw/2+off, x2=colX(t.up.col)+lw/2+off, y1=Y(t.lo.E), y2=Y(t.up.E);
    const col=t.cat==='ok'?(t.nm>=380&&t.nm<=750?nmColor(t.nm):t.nm<380?'#7a5cff':'#8b1a1a'):GCAT[t.cat][1]; const dash={ok:'',lap:'stroke-dasharray="5 4"',dl:'stroke-dasharray="9 4"',spin:'stroke-dasharray="8 3 2 3"',J:'stroke-dasharray="2 3"'}[t.cat];
    const [ya,yb]=grMode==='abs'?[y1,y2]:[y2,y1], [xa,xb]=grMode==='abs'?[x1,x2]:[x2,x1], sel=grSel===t.lo.c+'|'+t.up.c;
    s+=`<line x1="${xa}" y1="${ya}" x2="${xb}" y2="${yb}" stroke="${col}" stroke-width="${sel?4:t.cat==='ok'?2.2:1.7}" ${dash} ${t.calc?'opacity=".7"':''} marker-end="url(#gra)"/>`;
    if(t.cat!=='ok'&&t.cat!=='spin') s+=`<text x="${(xa+xb)/2+3}" y="${(ya+yb)/2}" font-size="12" font-weight="700" fill="${col}">✗</text>`; });
  // niveles (clicables), rótulos sin superponerse por columna
  const ly={}; L.map((l,i)=>({l,i})).sort((a,b)=>a.l.E-b.l.E).forEach(({l,i})=>{ const c=l.col, y=Y(l.E)+4; ly[i]=Math.min(y,(ly['c'+c]!=null?ly['c'+c]-10:y)); ly['c'+c]=ly[i]; });
  L.forEach((l,i)=>{ const x=colX(l.col), y=Y(l.E), on=grLv===i; s+=`<g data-lv="${i}" style="cursor:pointer"><rect x="${x-4}" y="${y-6}" width="${lw+8}" height="12" fill="transparent"/><line x1="${x}" y1="${y}" x2="${x+lw}" y2="${y}" stroke="${l.core?'#6b7280':ink}" stroke-width="${on?4.4:2.4}" ${l.calc?'stroke-dasharray="4 3"':''}/>${on?`<line x1="${x-3}" y1="${y}" x2="${x+lw+3}" y2="${y}" stroke="#f59f00" stroke-width="8" opacity=".35"/>`:''}<text x="${x+lw+4}" y="${ly[i]}" font-size="10" fill="${l.calc?mut:ink}">${l.c}${l.calc?' ≈':''}</text></g>`; });
  // leyenda
  const lg=[['ok','permitida (color = región)'],['spin','intercombinación ΔS ≠ 0'],['lap','Laporte (misma paridad)'],['dl','ΔL o Δl > 1'],['J','J 0↔0 / ΔJ > 1']]; s+=lg.map(([k,t],q)=>`<g transform="translate(${[8,200,392,8,200][q]},${q<3?H-20:H-4})"><line x1="0" y1="-4" x2="22" y2="-4" stroke="${k==='ok'?'#1c6dd0':GCAT[k][1]}" stroke-width="2.4" ${({ok:'',lap:'stroke-dasharray="5 4"',dl:'stroke-dasharray="9 4"',spin:'stroke-dasharray="8 3 2 3"',J:'stroke-dasharray="2 3"'})[k]}/><text x="26" y="0" font-size="10" fill="${mut}">${t}</text></g>`).join('');
  s+='</svg>'; $('#grFig').innerHTML=s;
  $('#grSvg').querySelectorAll('[data-lv]').forEach(g=>g.addEventListener('click',()=>{ const i=+g.dataset.lv; grLv=grLv===i?null:i; grSel=null; renderGrot(); }));
  const ok=show.filter(t=>t.cat==='ok'); const lo=ok.length?ok.reduce((a,b)=>a.nm>b.nm?a:b):null, hi=ok.length?ok.reduce((a,b)=>a.nm<b.nm?a:b):null;
  const tr=t=>(grMode==='abs'?t.lo.c+(t.Jl!=null&&G.one&&(t.lo.Js||t.up.Js)?'<sub>'+jTxt(t.Jl)+'</sub>':'')+' → '+t.up.c+(t.Ju!=null&&G.one&&(t.lo.Js||t.up.Js)?'<sub>'+jTxt(t.Ju)+'</sub>':''):t.up.c+(t.Ju!=null&&G.one&&(t.lo.Js||t.up.Js)?'<sub>'+jTxt(t.Ju)+'</sub>':'')+' → '+t.lo.c+(t.Jl!=null&&G.one&&(t.lo.Js||t.up.Js)?'<sub>'+jTxt(t.Jl)+'</sub>':''));
  const lam=t=>t.nm>=1e5?fmt(t.nm/1e6,2)+' mm':t.nm>=5000?fmt(t.nm/1000,1)+' μm':fmt(t.nm,t.nm<1000?2:0)+' nm';
  $('#grTab').innerHTML=`<table><thead><tr><th>Transición</th><th>¿Permitida?</th><th>λ en aire</th><th>Energía (eV)</th><th>Región</th><th>AA</th><th>EA</th></tr></thead><tbody>${show.slice(0,160).map(t=>{ const key=t.lo.c+'|'+t.up.c; return `<tr data-k="${key}" style="cursor:pointer${grSel===key?';background:var(--accent-soft)':''}"><td>${tr(t)}${t.calc?' <span class="caption">(≈ calc.)</span>':''}</td><td class="wrap"><span style="color:${t.cat==='ok'?'#2b8a3e':GCAT[t.cat][1]};font-weight:600">${t.cat==='ok'?'✓':t.cat==='spin'?'≈':'✗'}</span> ${t.cat==='ok'?(G.one?'Δl = ±1, cambia la paridad':'cambia la paridad, ΔL y ΔJ = 0, ±1, ΔS = 0'):GCAT[t.cat][0]}${t.cat==='spin'?(grK==='He'?': no se observa (átomo ligero)':grK==='Hg'||grK==='Cd'?': observable, el espín–órbita mezcla singletes y tripletes':': débil'):''}</td><td>${t.cat==='ok'||t.cat==='spin'?lam(t):'—'}</td><td>${fmt(t.eV,3)}</td><td>${region(t.nm)}${t.nm>=380&&t.nm<=750?` <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:${nmColor(t.nm)}"></i>`:''}</td><td>${t.ok&&t.res?'sí':'—'}</td><td>${t.ok?'sí':'—'}</td></tr>`; }).join('')}</tbody></table>${show.length>160?`<p class="caption">Se muestran 160 de ${show.length}; toca un nivel para ver solo los suyos.</p>`:''}`;
  $('#grTab').querySelectorAll('tr[data-k]').forEach(r=>r.onclick=()=>{ grSel=r.dataset.k; renderGrot(); });
  const sel=grLv!=null?L[grLv]:null, cnt=c=>show.filter(t=>t.cat===c).length;
  $('#grOut').innerHTML=`${sel?`<p><b>Nivel ${sel.c}</b>${sel.calc?' (energía estimada con el defecto cuántico)':''}: ${cnt('ok')} transiciones permitidas, ${cnt('spin')} de intercombinación, ${cnt('lap')+cnt('dl')+cnt('J')} prohibidas. Toca otra vez el nivel para volver.</p>`:''}<p>${grMode==='abs'?'<b>Absorción (AA):</b> casi todos los átomos están en el estado fundamental, así que solo se absorben las líneas que parten de él (líneas de resonancia).':'<b>Emisión (EA, llama o plasma):</b> los átomos excitados bajan por cualquier camino permitido; aparecen también líneas entre niveles excitados.'} ${lo&&!sel?`Línea de <b>menor energía</b>: ${tr(lo)}, ${lam(lo)} (${fmt(lo.eV,3)} eV). Línea de <b>mayor energía</b>: ${tr(hi)}, ${lam(hi)} (${fmt(hi.eV,3)} eV).`:''}</p><p>${G.note}</p><p class="caption">Reglas (dipolo eléctrico): cambia la paridad (Laporte); para un electrón Δl = ±1; ΔL = 0, ±1 (no 0 → 0); ΔJ = 0, ±1 (no 0 → 0); ΔS = 0. Las «prohibidas» no tienen intensidad exactamente cero: aparecen como cuadrupolo eléctrico o dipolo magnético, de 10⁵ a 10⁸ veces más débiles. Toca un nivel del diagrama para ver todas sus transiciones, también las prohibidas. Niveles: NIST (Handbook of Basic Atomic Spectroscopic Data y ASD); «≈» = estimado con el defecto cuántico; λ en aire (fórmula de Edlén) por encima de 200 nm.</p><div class="note"><b>¿Y el campo cristalino?</b> Aquí el átomo está libre (gas): los cinco orbitales d tienen la misma energía y no hay desdoblamiento t<sub>2g</sub>/e<sub>g</sub>. Un salto d → d no cambia la paridad, así que en el átomo libre está prohibido por Laporte (míralo en el Cu: 4s → 3d⁹4s²). En un complejo los ligandos separan los d y la vibración relaja un poco la regla: aparecen las bandas d–d, débiles. <a href="#colorD">Ver por qué hay color de d⁰ a d¹⁰ →</a></div>`;
  renderBoltz(); }

function renderBoltz(){ const G=GROT[grK], T=+$('#gbT').value; const first=G.lev.filter(l=>l.E>0&&(G.hg?l.c.includes('¹P₁')||l.c.includes('³P₁'):l.l===1)).sort((a,b)=>a.E-b.E)[0]; if(!first) return; const g0=G.lev[0].g, dE=first.E/8065.544, r=first.g/g0*Math.exp(-dE/(8.617333e-5*T));
  $('#gbOut').innerHTML=`Nivel ${first.c} (ΔE = ${fmt(dE,3)} eV, g* = ${first.g}, g₀ = ${g0}): N*/N₀ = (g*/g₀)·e<sup>−ΔE/kT</sup> = <b>${sci(r,2)}</b> a ${T} K. ${r<1e-3?'Prácticamente todos los átomos están en el estado fundamental: por eso la absorción (AA) es sensible y casi no depende de la temperatura, mientras que la emisión depende muchísimo de T.':'Una fracción apreciable está excitada: la emisión (EA, ICP-OES) se vuelve muy sensible.'}`; }
