function clipPoly(pts,n,d){ const out=[]; for(let i=0;i<pts.length;i++){ const a=pts[i], b=pts[(i+1)%pts.length], sa=v3dot(a,n)-d, sb=v3dot(b,n)-d; if(sa<=0) out.push(a); if(sa*sb<0){ const t=sa/(sa-sb); out.push(v3add(a,v3s(v3sub(b,a),t))); } } return out; }
