  if(pz.lab&&pz.lens!=='art') P.V.forEach((v,i)=>{ const p=proj(...v3s(v,1.08),sc); items.push({z:-1e3,layer:2,draw:c=>{ c.fillStyle='#fff'; c.beginPath(); c.arc(p[0],p[1],9,0,7); c.fill(); c.fillStyle='#141b26'; c.font='700 11px IBM Plex Sans, sans-serif'; c.textAlign='center'; c.fillText(i+1,p[0],p[1]+4); c.textAlign='left'; }}); });
