const PZCH=[['Encuentra un corte del cubo que dé un hexágono regular.',()=>POLY[pz.i].k==='cube'&&pz.sec&&pz.sec.length===6],['Muestra los ejes de un sólido que tenga ejes C₅.',()=>pz.sym==='axes'&&POLY[pz.i].sym.axes.some(a=>a.n===5)],['Elige el deltaedro de closo-[B₆H₆]²⁻.',()=>POLY[pz.i].k==='octa'],['Activa el dual del cubo y comprueba que es un octaedro.',()=>POLY[pz.i].k==='cube'&&pz.dual],['Encuentra un poliedro sin centro de inversión pero con 6 planos de simetría.',()=>{ const S=POLY[pz.i].sym; return !S.inv&&S.planes.length===6; }],['Haz una composición con una simetría que un cristal no admite.',()=>pz.lens==='art'&&[5,7,8,9,10,11,12].includes(pz.mods)],['Corta el octaedro por el plano ecuatorial (sección cuadrada).',()=>POLY[pz.i].k==='octa'&&pz.sec&&pz.sec.length===4]];
function pzNew(){ pz.ch=PZCH[Math.floor(Math.random()*PZCH.length)]; $('#pzCh').textContent=pz.ch[0]; $('#pzFb').textContent=''; }
function pzAll(){ pzView.render(); pzInfo(); }
let pzDone=false;
function renderPoli(){ if(pzDone){ pzAll(); return; } pzDone=true; pzView=orbitCanvas($('#pzCv'),480,pzDraw);
  pickRow('#pzPick',POLY,pz.i,i=>{ pz.i=i; pz.symI=0; pzAll(); },x=>x.n); bindSeg('#pzLens','m',v=>{ pz.lens=v; $('#pzArtBox').hidden=v!=='art'; pzAll(); }); bindSeg('#pzDrawSeg','m',v=>{ pz.draw=v; pzAll(); }); bindSeg('#pzSymSeg','m',v=>{ pz.sym=v; pzAll(); });
  $('#pzLab').addEventListener('change',e=>{ pz.lab=e.target.checked; pzAll(); }); $('#pzDual').addEventListener('change',e=>{ pz.dual=e.target.checked; pzAll(); });
  [['#pzExp','exp'],['#pzCut','cut'],['#pzMods','mods'],['#pzRad','rad']].forEach(([id,k])=>$(id).addEventListener('input',e=>{ pz[k]=+e.target.value; $(id+'v').textContent=k==='rad'?fmt(pz[k],1):pz[k]+(k==='mods'?'':' %'); pzAll(); }));
  $('#pzCutN').addEventListener('change',e=>{ pz.cutN=+e.target.value; pzAll(); }); $('#pzPrev').onclick=()=>{ pz.symI=Math.max(0,pz.symI-1); pzAll(); }; $('#pzNext').onclick=()=>{ pz.symI++; pzAll(); };
  $('#pzChk').onclick=()=>{ if(!pz.ch) pzNew(); const ok=pz.ch[1](); $('#pzFb').textContent=ok?'¡Logrado! +20 puntos. Piensa qué propiedad usaste.':'Todavía no: sigue manipulando y vuelve a comprobar.'; $('#pzFb').style.color=ok?'var(--up)':'var(--down)'; if(ok){ pz.score+=20; $('#pzSc').textContent=pz.score+' pts'; PG.add('POLI',true); setTimeout(pzNew,1400); } }; $('#pzNewB').onclick=pzNew;
  try{ $('#pzNote').value=localStorage.getItem('cristalia-pznote')||''; }catch(e){} $('#pzSave').onclick=()=>{ try{ localStorage.setItem('cristalia-pznote',$('#pzNote').value); $('#pzFb').textContent='Nota guardada en este navegador.'; }catch(e){ $('#pzFb').textContent='Este navegador no permite guardar.'; } };
  ['#pzExp','#pzCut'].forEach(id=>$(id+'v').textContent='0 %'); $('#pzModsv').textContent=pz.mods; $('#pzRadv').textContent=fmt(pz.rad,1); pzNew(); pzAll(); }

