// ---------- atrano idealizado C3v ----------
const ATR={Si:{dMN:2.17,dMO:1.66,ap:['C',1.87],n:'1-metilsilatrano',ang:84},Ti:{dMN:2.30,dMO:1.86,ap:['O',1.80],n:'titanatrano (con un alcóxido apical, idealizado)',ang:80},Al:{dMN:2.08,dMO:1.76,ap:null,n:'alumatrano monomérico ideal (en la realidad se oligomeriza)',ang:82}};
