  if(li){ const c2=axes.filter(x=>x.n!==Infinity&&Math.abs(v3dot(x.d,li.d))<0.02); axes=[li].concat(c2.length?[Object.assign(c2[0],{n:2,inf:true})]:[]);
    const pv=planes.filter(p=>Math.abs(v3dot(p.n,li.d))<0.02), ph=planes.filter(p=>Math.abs(v3dot(p.n,li.d))>0.98); planes=(pv.length?[Object.assign(pv[0],{t:'σv',inf:true})]:[]).concat(ph.map(p=>Object.assign(p,{t:'σh'}))); }
  else { const nmax=Math.max(0,...axes.map(x=>x.n)), prin=axes.filter(x=>x.n===nmax), cubic=axes.filter(x=>x.n>=3).length>1, c4=axes.filter(x=>x.n===4);
    planes.forEach(p=>{ if(cubic) p.t=c4.some(x=>Math.abs(v3dot(x.d,p.n))>0.98)?'σh':'σd'; else if(prin.length===1&&nmax>=2){ const dd=Math.abs(v3dot(p.n,prin[0].d)); p.t=dd>0.98?'σh':dd<0.02?'σv':'σ'; } else p.t='σ'; }); }
