  const pa=ax.find(x=>x.n===nmax).d, perp=ax.filter(x=>x.n===2&&Math.abs(v3dot(x.d,pa))<0.02).length, sh=pl.some(q=>Math.abs(v3dot(q.n,pa))>0.98), sv=pl.filter(q=>Math.abs(v3dot(q.n,pa))<0.02).length;
