const SYC={2:'#15803d',3:'#ea580c',4:'#2563eb',5:'#a21caf',6:'#7c3aed',Infinity:'#475569'};
const SPC={'σh':'#d97706','σv':'#0284c7','σd':'#0d9488','σ':'#0284c7'};
function symList(SY){ const L=[]; SY.axes.forEach((x,k)=>L.push({k:'a'+k,t:'C'+subI(x.n)+(x.inf?' (uno de infinitos)':'')})); SY.planes.forEach((x,k)=>L.push({k:'p'+k,t:x.t+(x.inf?' (uno de infinitos)':'')})); if(SY.inv) L.push({k:'i',t:'i (centro de inversión)'}); return L; }
function symItems(items,proj,sc,base,R){ const SY=molSym(base), sel=ml.symSel, C=SY.c, Lx=R+0.15, one=/^e:/.test(sel)?sel.slice(2):null;
  const showA=k=>one?one==='a'+k:(sel==='all'||sel==='axes'), showP=k=>one?one==='p'+k:(sel==='all'||sel==='planes'), showI=one?one==='i':(sel==='all'||sel==='axes');
  SY.axes.forEach((x,k)=>{ if(!showA(k)) return; const col=SYC[x.n]||'#475569', A=proj(...v3add(C,v3s(x.d,Lx)),sc), B=proj(...v3sub(C,v3s(x.d,Lx)),sc), M=proj(...C,sc), w=one?3.4:2.4;
    [[A,M],[M,B]].forEach(([p,q])=>items.push({z:(p[2]+q[2])/2-0.004,draw:c=>{ c.strokeStyle=col; c.lineWidth=w; c.setLineDash([8,5]); c.beginPath(); c.moveTo(p[0],p[1]); c.lineTo(q[0],q[1]); c.stroke(); c.setLineDash([]); }}));
    const F=A[2]<B[2]?A:B, dx=F[0]-M[0], dy=F[1]-M[1], L=Math.hypot(dx,dy)||1, tx=F[0]+dx/L*14, ty=F[1]+dy/L*14, t='C'+subI(x.n);
    items.push({z:-990,layer:2,draw:c=>{ c.font='700 14px IBM Plex Sans, sans-serif'; c.textAlign='center'; c.lineWidth=4; c.strokeStyle='rgba(255,255,255,.95)'; c.strokeText(t,tx,ty+5); c.fillStyle=col; c.fillText(t,tx,ty+5); c.textAlign='left'; }}); });
  SY.planes.forEach((x,k)=>{ if(!showP(k)) return; const col=SPC[x.t]||'#0284c7', F=frameOf(x.n), NW=28, rr=R+0.05, pts=[]; for(let q=0;q<NW;q++){ const t=q/NW*2*Math.PI; pts.push(proj(...v3add(C,v3add(v3s(F.e1,rr*Math.cos(t)),v3s(F.e2,rr*Math.sin(t)))),sc)); } const M=proj(...C,sc);
    for(let q=0;q<NW;q++){ const p1=pts[q], p2=pts[(q+1)%NW]; items.push({z:(p1[2]+p2[2]+M[2])/3+0.003,draw:c=>{ c.beginPath(); c.moveTo(M[0],M[1]); c.lineTo(p1[0],p1[1]); c.lineTo(p2[0],p2[1]); c.closePath(); c.globalAlpha=one?0.2:0.13; c.fillStyle=col; c.fill(); c.globalAlpha=0.85; c.strokeStyle=col; c.lineWidth=one?2.2:1.5; c.beginPath(); c.moveTo(p1[0],p1[1]); c.lineTo(p2[0],p2[1]); c.stroke(); c.globalAlpha=1; }}); }
    if(!one&&SY.planes.length>4) return; const T=pts.reduce((b,p)=>p[1]<b[1]?p:b,pts[0]); items.push({z:-985,layer:2,draw:c=>{ c.font='italic 700 14px IBM Plex Sans, sans-serif'; c.lineWidth=4; c.strokeStyle='rgba(255,255,255,.95)'; c.strokeText(x.t,T[0]+6+k*16,T[1]-4-k*13); c.fillStyle=col; c.fillText(x.t,T[0]+6+k*16,T[1]-4-k*13); }}); });
  if(SY.inv&&showI){ const M=proj(...C,sc); items.push({z:-995,layer:2,draw:c=>{ c.fillStyle='#be123c'; c.beginPath(); c.arc(M[0],M[1],4.5,0,7); c.fill(); c.font='italic 700 14px IBM Plex Sans, sans-serif'; c.lineWidth=4; c.strokeStyle='rgba(255,255,255,.95)'; c.strokeText('i',M[0]+7,M[1]+14); c.fillText('i',M[0]+7,M[1]+14); }}); } }
function symMap(op,t){ if(op.k==='i') return p=>v3s(p,1-2*t); if(op.k==='p'){ const n=op.o.n; return p=>v3sub(p,v3s(n,2*t*v3dot(p,n))); }
  const d=op.o.d, an=t*2*Math.PI/(op.o.n===Infinity?4:op.o.n), c=Math.cos(an), s=Math.sin(an); return p=>v3add(v3add(v3s(p,c),v3s(v3cr(d,p),s)),v3s(d,v3dot(d,p)*(1-c))); }
